import Link from "next/link";
import { guard, requireJv } from "@/lib/session";

import { todayIso } from "@/lib/dates";
import { ccyLabels, clientsOf, projectsOf } from "@/lib/lookups";
import { SOURCE_SYSTEMS } from "@/services/income";
import { externalInvoiceAction } from "../../actions";
import { ActionForm, CurrencyAmount, Submit } from "@/components/forms";
import { Hidden } from "@/components/doc-parts";
import { Notice, PageHead, Panel } from "@/components/ui";

export const metadata = { title: "Record external invoice" };

export default async function ExternalInvoice({ params }: { params: Promise<{ jv: string }> }) {
  const { jv } = await params;
  const ctx = await requireJv(jv);
  guard(ctx, "issue_invoice");
  const cl = await clientsOf(ctx);
  return (
    <>
      <PageHead title="Record an external invoice" crumbs={<Link href={`/j/${jv}/invoices`}>Invoices</Link>} context="For invoices generated by BusRep / TrackStar or InstaTickets. The portal records it by reference; it does not generate it." />
      {cl.length === 0 ? <Notice kind="warning" title="No clients yet"><Link href={`/j/${jv}/clients/new?back=/j/${jv}/invoices/external`}>Add the client first</Link>.</Notice> : (
        <Panel>
          <ActionForm action={externalInvoiceAction}><Hidden jv={jv} />
            <div className="form-row">
              <div className="field"><label htmlFor="sourceSystem">Source system</label><select id="sourceSystem" name="sourceSystem">{SOURCE_SYSTEMS.map((x) => <option key={x}>{x}</option>)}</select></div>
              <div className="field"><label htmlFor="externalNumber">Invoice number in that system</label><input id="externalNumber" name="externalNumber" /></div>
            </div>
            <div className="form-row">
              <div className="field"><label htmlFor="clientId">Client</label><select id="clientId" name="clientId">{cl.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}</select></div>
              <div className="field"><label htmlFor="projectId">Project</label><select id="projectId" name="projectId"><option value="">General</option>{(await projectsOf(ctx)).map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></div>
            </div>
            <div className="form-row">
              <div className="field"><label htmlFor="issueDate">Invoice date</label><input id="issueDate" type="date" name="issueDate" defaultValue={todayIso()} /></div>
              <div className="field"><label htmlFor="dueDate">Due date</label><input id="dueDate" type="date" name="dueDate" /></div>
            </div>
            <CurrencyAmount currencies={ctx.jv.currencies} labels={ccyLabels} currencyName="currency" amountName="amount" amountLabel="Invoice total (including VAT)" />
            <div className="field"><label htmlFor="file">Invoice PDF from the source system</label><input id="file" type="file" name="file" accept=".pdf,.jpg,.jpeg,.png" /></div>
            <div className="field"><label htmlFor="notes">Notes</label><textarea id="notes" name="notes" style={{ minHeight: 64 }} /></div>
            <div className="form-actions"><Submit>Record invoice</Submit></div>
          </ActionForm>
        </Panel>
      )}
    </>
  );
}
